/**
 * Dashboard v2 « Pilotage stocks emballage » for the mock backend.
 *
 * The fixture holds a dashboard spec and DashboardDataResponse payloads that
 * were generated by the REAL engine (synthetic data), one per filter state:
 *   { dashboard, responses: { "<famille or empty>|<periode>": response } }
 * The mock serves the response of the requested state, or the nearest one the
 * fixture holds (same famille first, then the closest period).
 *
 * MOCK_BI_FIXTURE=<path> loads another file with the same shape (full set of
 * states, for instance) instead of the light one kept in the repository.
 */
import fs from "node:fs";

const DEFAULT_FIXTURE = new URL("./fixtures/dashboard-v2-stock.json", import.meta.url);
const PERIODS = ["13w", "26w", "52w", "all"];
const ALIAS = { "3m": "13w", "6m": "26w", "12m": "52w" };

const clone = (x) => JSON.parse(JSON.stringify(x));
let fixture = null;

function load() {
  if (!fixture) {
    const file = process.env.MOCK_BI_FIXTURE || DEFAULT_FIXTURE;
    fixture = JSON.parse(fs.readFileSync(file, "utf8"));
    // The UI addresses the demo dashboard by a stable id and slug.
    fixture.dashboard.id = "v2-stock";
    fixture.dashboard.slug = "pilotage-stocks-emballage";
    fixture.dashboard.status = "published";
    fixture.dashboard.visibility = "private";
  }
  return fixture;
}

export const loadDashboard = () => clone(load().dashboard);

function periodDistance(a, b) {
  return Math.abs(PERIODS.indexOf(a) - PERIODS.indexOf(b));
}

/** The stored response closest to the requested filter state. */
export function pickResponse(body = {}) {
  const { responses } = load();
  const famille = body.filters?.famille ?? "";
  const raw = body.filters?.periode === undefined ? "26w" : body.filters.periode;
  const periode = raw == null ? "all" : ALIAS[raw] || raw;
  const exact = `${famille}|${periode}`;
  if (responses[exact]) return responses[exact];
  const keys = Object.keys(responses).map((k) => {
    const [f, p] = k.split("|");
    return { k, f, p };
  });
  const rank = (e) => (e.f === famille ? 0 : 10) + periodDistance(e.p, periode);
  keys.sort((a, b) => rank(a) - rank(b));
  return responses[keys[0].k];
}

/** A component added through the editor has no stored result: borrow a similar one. */
function borrow(visual, response) {
  const results = Object.entries(response.components);
  const same = results.find(([, r]) => r.type === visual.type && (visual.type !== "kpi" || r.meta?.measures?.[0]?.name === visual.kpi?.measure));
  if (same) return clone(same[1]);
  const kind = results.find(([, r]) => r.type === visual.type);
  if (kind) return clone(kind[1]);
  if (visual.type === "kpi") {
    return { type: "kpi", rows: null, value: { value: null, formatted: "—", status: null, delta: null, delta_formatted: null, secondary: null, target_label: null }, text: null, badges: null, reference_lines: [], meta: { source: visual.source, measures: [], filters_applied: {}, ignored_filters: [], row_count: 0, provenance: [], warnings: [] }, error: null };
  }
  return { type: visual.type, rows: [], value: null, text: null, badges: null, reference_lines: [], meta: { source: visual.source, measures: [], filters_applied: {}, ignored_filters: [], row_count: 0, provenance: [], warnings: [] }, error: null };
}

export function computeData(dashboard, body = {}) {
  const base = clone(pickResponse(body));
  const first = load().responses["|26w"] || Object.values(load().responses)[0];
  base.sources = base.sources || clone(first.sources);
  base.filter_options = base.filter_options || clone(first.filter_options);
  base.dashboard_id = dashboard.id;
  const components = {};
  for (const c of dashboard.components) {
    if (body.components && !body.components.includes(c.id)) continue;
    if (c.component_type !== "visual") continue;
    components[c.id] = base.components[c.id] || borrow(c.visual, base);
  }
  base.components = components;
  base.generated_at = new Date().toISOString();
  return base;
}

let nextId = 1;

/** Applies PatchOps to the dashboard in memory (what the editor needs). */
export function applyOps(dashboard, ops) {
  const source = (name) => dashboard.sources.find((s) => s.name === name);
  for (const op of ops || []) {
    switch (op.op) {
      case "set_title":
        dashboard.title = op.title;
        if (op.description !== undefined) dashboard.description = op.description;
        break;
      case "move_component": {
        const c = dashboard.components.find((x) => x.id === op.component_id);
        if (c) c.position = { ...c.position, ...op.position };
        break;
      }
      case "update_visual": {
        const c = dashboard.components.find((x) => x.id === op.component_id);
        if (c) c.visual = { ...c.visual, ...op.changes };
        break;
      }
      case "add_visual": {
        const bottom = dashboard.components.reduce((m, c) => Math.max(m, c.position.row + c.position.height), 0);
        dashboard.components.push({
          id: op.component_id || `mock-${nextId++}`,
          component_type: "visual",
          position: op.position || { row: bottom, col: 0, width: 4, height: 3 },
          visual: op.visual,
        });
        break;
      }
      case "remove_component":
        dashboard.components = dashboard.components.filter((x) => x.id !== op.component_id);
        break;
      case "upsert_measure": {
        const s = source(op.source);
        if (!s) break;
        const i = s.measures.findIndex((m) => m.name === op.measure.name);
        if (i >= 0) s.measures[i] = op.measure;
        else s.measures.push(op.measure);
        break;
      }
      case "remove_measure": {
        const s = source(op.source);
        if (s) s.measures = s.measures.filter((m) => m.name !== op.name);
        break;
      }
      case "upsert_filter": {
        const i = dashboard.filters.findIndex((f) => f.id === op.filter.id);
        if (i >= 0) dashboard.filters[i] = op.filter;
        else dashboard.filters.push(op.filter);
        break;
      }
      case "remove_filter":
        dashboard.filters = dashboard.filters.filter((f) => f.id !== op.id);
        break;
      case "upsert_source": {
        const i = dashboard.sources.findIndex((s) => s.name === op.source.name);
        if (i >= 0) dashboard.sources[i] = op.source;
        else dashboard.sources.push(op.source);
        break;
      }
      case "remove_source":
        dashboard.sources = dashboard.sources.filter((s) => s.name !== op.name);
        break;
      default:
        break;
    }
  }
  return dashboard;
}
